    + (alt.length ? ' '+alt.slice(0, 3).join(', ').replace(/, ([^,]*)$/, ' and $1')+' '+(alt.length === 1 ? 'has' : 'have')+' '+(PL.length === 2 ? 'both' : 'all '+PL.length)+', if you use '+(alt.length === 1 ? 'that book' : 'those books')+'.' : '');
